import{_ as e,o as a,c as s,a5 as r}from"./chunks/framework.BwlBv862.js";const k=JSON.parse('{"title":"現在の通信経路と環境の制限","description":"","frontmatter":{"title":"現在の通信経路と環境の制限","docId":"developer.transports","translationKey":"developer.transports","locale":"ja","audience":"developer","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"6696987a0db16b3b4d364c6136d0e552dbebd6fc68346e3ed031587a7b004468","translationRevision":"8c906798c481cda745d80d2b11ccfe73a2ab9d171780c591052631b292df8292","order":200},"headers":[],"relativePath":"ja/developer/transports.md","filePath":"ja/developer/transports.md","lastUpdated":1794611623000}'),i={name:"ja/developer/transports.md"};function o(d,t,n,l,p,h){return a(),s("div",null,[...t[0]||(t[0]=[r(`<h1 id="current-transports-and-platform-restrictions" tabindex="-1">現在の通信経路と環境の制限 <a class="header-anchor" href="#current-transports-and-platform-restrictions" aria-label="Permalink to &quot;現在の通信経路と環境の制限 {#current-transports-and-platform-restrictions}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目的と前提条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目的と前提条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>対象ビルドと環境に実在する通信経路を選びます。<a href="./control-api.html">Control API</a> と<a href="./collaboration.html">共同操作</a> を読みます。通信は直列化した操作を運び、別コアや独自の権限を作ってはいけません。</p><h2 id="choose-the-boundary" tabindex="-1">境界を選ぶ <a class="header-anchor" href="#choose-the-boundary" aria-label="Permalink to &quot;境界を選ぶ {#choose-the-boundary}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>経路</th><th>現在の実装</th><th>主な制限</th></tr></thead><tbody><tr><td>デスクトップ WebView</td><td>Wry IPC と共有制御クライアント</td><td>GUI・スレッドの寿命はデスクトップ所有</td></tr><tr><td>ローカル CLI</td><td>Unix ソケットか Windows 名前付きパイプ、明示的 stdio ホスト</td><td>同じホームと所有者</td></tr><tr><td>ローカルブラウザー</td><td>ネイティブループバックアダプターと <code>browser-transport.ts</code></td><td>ペアリング済みホスト。モックや公開リモートサーバーではない</td></tr><tr><td>直接リモート</td><td>認証付き HTTPS/WSS ゲートウェイと SDK・ブラウザー通信</td><td>TLS、hello、権限、機能条件</td></tr><tr><td>ネイティブ peer</td><td><code>tiktools-peer</code>、暗号化 iroh/QUIC ストリーム</td><td>peer ID だけでは RPC 権限を得ない</td></tr><tr><td>ネイティブ WebRTC</td><td><code>tiktools-rtc</code>、署名付きシグナリングとデータチャネル</td><td>交渉、権限、経路確認も必要</td></tr></tbody></table><p>TypeScript インターフェースは <code>src/web/shared/api/control-transport.ts</code> にあります。ネイティブ peer 設定は公開第三者リレーや探索を暗黙に有効化しません。WebRTC は Rust ネイティブ (<code>webrtc</code> 0.21.1) で、デスクトップ UI のブラウザー <code>RTCPeerConnection</code> 依存ではありません。</p><h2 id="inspect-the-selected-route" tabindex="-1">選択経路を調べる <a class="header-anchor" href="#inspect-the-selected-route" aria-label="Permalink to &quot;選択経路を調べる {#inspect-the-selected-route}&quot;">​</a></h2><p>ペアリングやコントローラー操作の表示前に、接続ホストのメソッドと機能を検出します。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> discover</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> browser-transport</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote-browser-transport</span></span></code></pre></div><p><code>tiktools-rtc/src/route.rs</code> は選択された ICE 候補対から直接・リレーを分類します。準備完了だけでは直接経路を証明しません。Cloud のシグナリング・リレー基盤は業務認可とは別で、ネイティブ権限検査を維持します。</p><h2 id="expected-result-and-status" tabindex="-1">期待される結果と提供状況 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;期待される結果と提供状況 {#expected-result-and-status}&quot;">​</a></h2><p>ローカル IPC とデスクトップ通信は確立済みです。ネイティブ peer、WebRTC、コントローラー連携にはソースと対象テストがありますが、配置と複数 PC の受け入れは実験段階です。peer/relay が未実装とする旧記述は過去のものです。Android のローカル IPC は動作しますが、永続リモートプロファイル用ストアは未選択で、ネイティブアドオンと WebView は使えません。</p><h2 id="recovery" tabindex="-1">問題が起きたとき <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;問題が起きたとき {#recovery}&quot;">​</a></h2><p>切断後、受け付け済み操作は結果不明になり得ます。再接続では非公開投影を無効化し、ID を再交渉して上限付きストリームを再開・再取得します。証明書検査を弱めたり、リモート失敗から黙ってローカル所有者へ切り替えたりしません。<a href="https://github.com/nglmercer/TikTools-app/tree/remake/crates/tiktools-rtc/src" target="_blank" rel="noreferrer">RTC 実装</a> と実際の機能グラフが古い計画に優先します。</p><h2 id="operational-details" tabindex="-1">運用の詳細 <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;運用の詳細 {#operational-details}&quot;">​</a></h2><p>Peer は ALPN <code>tiktools/collaboration/1</code>、現在 15 秒の接続 timeout、明示構成した最大 4 relay を使います。Peer/RTC フレームは 1 MiB、RTC パケットは最大 16 KiB です。過大フレームは検証で拒否し、部分 RPC にはしません。構成・ID、信号処理、timeout、サイズ、認可を分けて調べます。Cloud relay は ICE TURN サーバーではなく、空リストは公開 discovery を有効にしません。ホスト・端末の稼働と現在の確認済み grant を確認し、ICE の直通/relay 経路を記録します。ready・暗号化だけでは RPC 権限も全 NAT 通過も証明できません。実機 2 台の前にセッション変更・失効と過大フレームを fixtures で検証します。</p>`,16)])])}const u=e(i,[["render",o]]);export{k as __pageData,u as default};
